    color-scheme: light;
    --toastify-color-light: #9ca0b0;
    --toastify-text-color-light: #4c4f69;
    --toastify-color-info: #1e66f5;
    --toastify-color-success: #40a02b;
    --toastify-color-warning: #df8e1d;
