    border-color: transparent;
    box-shadow: rgba(204, 208, 218, 0.1) 0 1px 1px, rgba(204, 208, 218, 0.15) 0 2px 2px, rgba(204, 208, 218, 0.2) 0 4px 4px;
  }
  :root .card#listen-count-card {
    margin-bottom: 5px;
    border-color: #bcc0cc;
  }
